CREATE TABLE camera_offsets (
    camera_id TEXT PRIMARY KEY,
    dvr_minus_utc_s INTEGER NOT NULL
);

CREATE TABLE cctv_motion (
    motion_id TEXT PRIMARY KEY,
    camera_id TEXT NOT NULL,
    raw_dvr_epoch INTEGER NOT NULL
);

CREATE TABLE smart_lock_log (
    lock_event_id TEXT PRIMARY KEY,
    door_id TEXT NOT NULL,
    ntp_utc_epoch INTEGER NOT NULL
);

