    {"ts": "2021-10-14T23:18:18Z", "event_type": "PAGING_TIMEOUT", "cgi": "310-260-4410-01"},
    {"ts": "2021-10-14T23:18:26Z", "event_type": "PAGING_TIMEOUT", "cgi": "310-260-4410-01"},
]
