    nodes: set[str] = set()
    for e in edges:
        adj[e["u"]].add(e["v"])
        adj[e["v"]].add(e["u"])
        nodes.update([e["u"], e["v"]])
    if not reachable(adj, src, dst):
        return []
    return sorted(n for n in (nodes - {src, dst}) if not reachable(adj, src, dst, banned_node=n))

