def adamic_adar_jaccard(entity_attrs: dict[str, set[str]], attr_degrees: dict[str, int], a: str, b: str) -> dict:
    set_a, set_b = entity_attrs.get(a, set()), entity_attrs.get(b, set())
    inter = set_a & set_b
