def verify_ellipsis_quote(excerpt: str, source_doc: str, max_gap_chars: int = 120) -> dict:
    if "..." not in excerpt:
        exact = excerpt in source_doc
        return {"status": "VERIFIED_CONTIGUOUS" if exact else "NOT_FOUND", "omitted_polarity": []}
    parts = [p.strip() for p in excerpt.split("...") if p.strip()]
    if len(parts) != 2:
        return {"status": "MULTI_ELLIPSIS_REJECTED", "omitted_polarity": []}
    left, right = parts
    i_left = source_doc.find(left)
    if i_left == -1:
        return {"status": "LEFT_SPAN_NOT_FOUND", "omitted_polarity": []}
    i_mid_start = i_left + len(left)
    i_right = source_doc.find(right, i_mid_start)
    if i_right == -1 or (i_right - i_mid_start) > max_gap_chars:
        return {"status": "RIGHT_SPAN_INVALID", "omitted_polarity": []}
    omitted_span = source_doc[i_mid_start:i_right]
    words = {w.lower() for w in re.findall(r"[a-zA-Z']+", omitted_span)}
    bad_tokens = sorted(words & POLARITY_TOKENS)
    return {
        "status": "REJECTED_POLARITY_OMISSION" if bad_tokens else "VERIFIED_SAFE_ELLIPSIS",
