    mad = max(1e-6, median_val(abs_devs))
    flagged = []
    for r in invoices:
        p = float(r["unit_price_usd"])
        mod_z = 0.6745 * (p - med) / mad
        if abs(mod_z) > threshold:
            flagged.append({
                "invoice_id": r["invoice_id"],
                "unit_price_usd": p,
                "peer_median_usd": round(med, 2),
                "modified_z": round(mod_z, 2),
                "direction": "OVER_INVOICED_CAPITAL_FLIGHT" if mod_z > 0 else "UNDER_INVOICED_DUTY_OR_VALUE_XFER",
            })
    return flagged

